#!/usr/bin/env python3
"""make_tables_jifma.py — tables and prose macros for the JIFMA manuscript (resubmission after the CGIR desk reject, strategy §7-A).

Runs make_tables_cgir.py first (all published tables and macros are inherited unchanged — the base results did not move), then adds the
exhibits of the stage-2 design battery and the validity audit. Rule unchanged: no number is typed into the manuscript; every cell and
every statistic in prose is generated here from a results file named in the fragment header.

New sources (all produced 2026-11-10/11):
  results/nested_models_20261110.json              ladder M0..M3 / F / K1 / S (cv AUC, Brier, paired-bootstrap increments), return ladder, decomposition of S
  results/cox_time_to_disposal_20261110.json       Cox (strata = period) HRs, Kaplan–Meier by signal tercile
  results/industry_fe_firm_clusters_20261110.json  year + GICS-sector FE, firm / two-way clustered p-values for the return, block and Gate-1 models
  results/matched_benchmark_selection_20261113.json 5x5 / 3x3 / matched-firm / PSM benchmarks; selection logit on the Compustat Global universe
  results/equity_did_appraisal_put_20261114.json   captive x post DiD against equity spin-offs; appraisal-price put tests; placebos
  results/protection_block_20261110.json           2022-10 shareholder-protection block: categories, strength, signal, disposal
  results/governance_controls_20261110.json        foreign ownership (KRX) and outside-director ratio (DART) added to the return and block regressions
  results/validity_bias_audit_20261111.json        subgroup AUC/calibration, anonymization, residual bias, two-model kappa, Kang & Lee benchmark
Output: paper/tables/T_*.tex, S_*.tex, numbers.tex (merged macros).
"""
import os, re, json, math, datetime as dt
P = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = open(f"{P}/code/make_tables_cgir.py", encoding="utf-8").read()
ns = {"__file__": f"{P}/code/make_tables_cgir.py", "__name__": "cgir_tables"}
exec(compile(src, "make_tables_cgir", "exec"), ns)            # inherits nums, r, pct, p, stars, mac, OUT, R, J
nums, r, pct, pv, stars, mac, OUT, R = ns["nums"], ns["r"], ns["pct"], ns["p"], ns["stars"], ns["mac"], ns["OUT"], ns["R"]
J = lambda name: json.load(open(f"{R}/{name}", encoding="utf-8"))
NM, CX, IF, MB, DP, PB, GC, VA = (J("nested_models_20261110.json"), J("cox_time_to_disposal_20261110.json"), J("industry_fe_firm_clusters_20261110.json"),
                                  J("matched_benchmark_selection_20261113.json"), J("equity_did_appraisal_put_20261114.json"), J("protection_block_20261110.json"),
                                  J("governance_controls_20261110.json"), J("validity_bias_audit_20261111.json"))
def w(name, body, srcs):
    open(f"{OUT}/{name}.tex", "w", encoding="utf-8").write(f"% generated by code/make_tables_jifma.py on {dt.date.today()} — source: {srcs}\n" + body + "\n")
def ci(v, d=3): return f"[{r(v[0], d)}, {r(v[1], d)}]"
def coefse(v, d=3, pkey="p_hc1"): return f"{r(v['coef'], d)}{stars(v.get(pkey))} ({r(v.get('se_hc1', v.get('se')), d)})"
def pp1(x): return r(x, 1)

# ---------------- Table 3 Panel A: nested ladder (27)
L = NM["ladder_pooled"]; LP = NM["ladder_by_period"]; INC = L["increments"]
rows = [("M0", "Financial covariates of the filing", "M0_financial", None), ("M1", "M0 + stated-purpose categories (Kang--Lee type)", "M1_plus_purpose", "M1_plus_purpose-M0_financial"),
        ("M2", "M1 + mention flags (buyer, investor, listing, protection, appraisal)", "M2_plus_mentions", "M2_plus_mentions-M1_plus_purpose"),
        ("M3", "M2 + disposal signal $S$", "M3_plus_signal", "M3_plus_signal-M2_plus_mentions"), ("F", "Extracted facts only (purpose + mentions)", "F_facts_only", None),
        ("K1", "M0 + keyword flags read from the raw text, no model", "K1_financial_plus_keywords", "K1_financial_plus_keywords-M0_financial"), ("S", "Signal alone", "S_signal_only_cv", None)]
body = ["\\begin{tabular}{l>{\\raggedright\\arraybackslash}p{6.0cm}cccrr}", "\\toprule", "Model & Inputs & CV AUC & Brier & $\\Delta$AUC [95\\% CI] & 2001--2016 & 2017+ \\\\", "\\midrule"]
for tag, lab, key, inc in rows:
    m = L[key]; d = f"{'+' if INC[inc]['point'] >= 0 else ''}{r(INC[inc]['point'], 3)} {ci(INC[inc]['ci95'])}" if inc else "--"
    body.append(f"{tag} & {lab} & {r(m['cv_auc'], 3)} & {r(m['brier_oof'], 3)} & {d} & {r(LP['2001-2016'][key]['cv_auc'], 3)} & {r(LP['2017+'][key]['cv_auc'], 3)} \\\\")
body += ["\\bottomrule", "\\end{tabular}"]
w("T_nested", "\n".join(body), "results/nested_models_20261110.json -> ladder_pooled, ladder_by_period, increments")
WORD = {"M0": "MZero", "M1": "MOne", "M2": "MTwo", "M3": "MThree", "F": "F", "K1": "KOne", "S": "S"}
for tag, lab, key, inc in rows: mac(f"Nested{WORD[tag]}", r(L[key]["cv_auc"], 3)); mac(f"Nested{WORD[tag]}Old", r(LP["2001-2016"][key]["cv_auc"], 3)); mac(f"Nested{WORD[tag]}New", r(LP["2017+"][key]["cv_auc"], 3))
mac("NestedIncMThreeMTwo", f"+{r(INC['M3_plus_signal-M2_plus_mentions']['point'], 2)}"); mac("NestedIncMThreeMTwoLo", r(INC['M3_plus_signal-M2_plus_mentions']['ci95'][0], 2)); mac("NestedIncMThreeMTwoHi", r(INC['M3_plus_signal-M2_plus_mentions']['ci95'][1], 2))
mac("NestedIncMOneMZero", f"+{r(INC['M1_plus_purpose-M0_financial']['point'], 2)}"); mac("NestedIncKOneMZero", f"+{r(INC['K1_financial_plus_keywords-M0_financial']['point'], 3)}")
mac("NestedIncMThreeMZero", f"+{r(INC['M3_plus_signal-M0_financial']['point'], 2)}")
lr = L.get("lr_tests_full_sample", {}); 
for k, v in lr.items():
    if "M3" in k and "M2" in k and isinstance(v, dict) and "p" in v: mac("NestedLRpMThree", "$<$0.001" if v["p"] < 0.001 else r(v["p"], 3))
DC = NM["decomposition_of_S"]; mac("DecompRTwo", r(DC["r2"], 2)); mac("DecompAUCFitted", r(DC["auc_S_hat_fitted_part"], 3)); mac("DecompAUCResid", r(DC["auc_S_resid"], 3))
mac("DecompSaleCoef", r(DC["coef"]["d_sale_or_disposal"]["coef"], 2)); mac("DecompFundCoef", r(DC["coef"]["d_fundraising_or_investment_attraction"]["coef"], 2)); mac("DecompInvestorCoef", r(DC["coef"]["d_mentions_external_investment_or_strategic_investor"]["coef"], 3))
RL = NM["return_ladder"]["rank_1y"]; mac("RankSPlusPurpose", r(RL["spec3_plus_purpose"]["p_llm"]["coef"], 3)); mac("RankSPlusPurposeP", pv(RL["spec3_plus_purpose"]["p_llm"]["p_hc1"]))
mac("RankSPlusPurposeMentions", r(RL["spec3_plus_purpose_mentions"]["p_llm"]["coef"], 3)); mac("RankSPlusPurposeMentionsP", pv(RL["spec3_plus_purpose_mentions"]["p_llm"]["p_hc1"]))
AL = NM["return_ladder"]["ann_car"]; mac("AnnSPlusPurposeMentions", r(AL["spec3_plus_purpose_mentions"]["p_llm"]["coef"], 3)); mac("AnnSPlusPurposeMentionsP", pv(AL["spec3_plus_purpose_mentions"]["p_llm"]["p_hc1"]))
PERM = NM["control_label_permutation"]; _pm = [v for k, v in PERM["mean"].items() if k != "noise10_features_real_labels"]; mac("PermAUCMin", r(min(_pm), 2)); mac("PermAUCMax", r(max(_pm), 2))


# ---------------- Table 3 Panel B: Cox (28)
A = CX["models"]["A"]["cox_strata_period"]; H = A["hr"]; hr_sd = CX["expectation_check"]["HR_S_per_sd"]
sd_S = math.log(hr_sd) / math.log(H["S"]["hr"])                     # implied SD of S in the Cox sample (HR_sd = HR_unit^sd)
sd_ci = [math.exp(math.log(H["S"]["ci95"][0]) * sd_S), math.exp(math.log(H["S"]["ci95"][1]) * sd_S)]
mac("ScoreSD", r(sd_S, 2))
# DB HiTek (rcept 20230502000307), the worked example of a small-block parent that bound itself: controlling block at the fiscal year-end before the 2023 announcement (ownership_pre_event_all.json)
mac("ExDBBlock", r(next(o["block_pct"] for o in json.load(open(f"{P}/data/processed/ownership_pre_event_all.json", encoding="utf-8")) if o["rcept_no"] == "20230502000307"), 0))
# block effect on S in units a reader can hold: per ten percentage points of the block, and that amount in standard deviations of S (block coefficient from the governance cross-section file make_tables_cgir reads)
_b = ns["GV"]["T2_score_on_block"]["block_controls"]["block"]["coef"]   # governance_cross_section_20261025.json, the regression behind \ScoreOnBlock (make_tables_cgir.py)
mac("ScoreOnBlockTenPP", r(_b / 10, 4)); mac("ScoreOnBlockTenPPSD", r(_b / 10 / sd_S, 2))
mac("ScoreOnBlockTenPPSDAbs", r(abs(_b / 10 / sd_S), 2))
KM = CX["kaplan_meier_sample_A"]["signal"]
body = ["\\begin{tabular}{lcccc}", "\\toprule", " & HR & 95\\% CI & $p$ & \\\\", "\\midrule",
        f"Disposal signal $S$, per standard deviation & {r(hr_sd, 2)} & {ci(sd_ci, 2)} & {pv(H['S']['p'])} & \\\\",
        f"Controlling block, per 10 pp & {r(H['block10']['hr'], 3)} & {ci(H['block10']['ci95'], 3)} & {pv(H['block10']['p'])} & \\\\",
        f"Relative size of the new company & {r(H['relative_size']['hr'], 2)} & {ci(H['relative_size']['ci95'], 2)} & {pv(H['relative_size']['p'])} & \\\\",
        f"Parent leverage after the division & {r(H['parent_after_leverage']['hr'], 2)} & {ci(H['parent_after_leverage']['ci95'], 2)} & {pv(H['parent_after_leverage']['p'])} & \\\\",
        f"log new-company assets & {r(H['log_newco_assets']['hr'], 3)} & {ci(H['log_newco_assets']['ci95'], 3)} & {pv(H['log_newco_assets']['p'])} & \\\\",
        f"KOSDAQ parent & {r(H['kosdaq']['hr'], 3)} & {ci(H['kosdaq']['ci95'], 3)} & {pv(H['kosdaq']['p'])} & \\\\",
        "\\midrule", "Kaplan--Meier share disposed by signal tercile & by year 1 & by year 3 & by year 5 & $n$ \\\\", "\\midrule"]
for lab, k in (("Low $S$", "low"), ("Middle", "mid"), ("High $S$", "high")):
    v = KM[k]; body.append(f"{lab} ({r(v['range'][0], 2)}--{r(v['range'][1], 2)}) & {pct(v['disposed_by_year_1'], 0)}\\% & {pct(v['disposed_by_year_3'], 0)}\\% & {pct(v['disposed_by_year_5'], 0)}\\% & {v['n']} \\\\")
body += ["\\bottomrule", "\\end{tabular}"]
w("T_cox", "\n".join(body), "results/cox_time_to_disposal_20261110.json -> models.A.cox_strata_period, kaplan_meier_sample_A, expectation_check.HR_S_per_sd")
mac("CoxN", A["n"]); mac("CoxEvents", A["events"]); mac("CoxConcordance", r(A["concordance"], 2)); mac("CoxHRSD", r(hr_sd, 2)); mac("CoxHRSDLo", r(sd_ci[0], 2)); mac("CoxHRSDHi", r(sd_ci[1], 2))
mac("CoxHRUnit", r(H["S"]["hr"], 1)); mac("CoxHRBlock", r(H["block10"]["hr"], 3)); mac("CoxHRBlockLo", r(H["block10"]["ci95"][0], 3)); mac("CoxHRBlockHi", r(H["block10"]["ci95"][1], 3))
mac("KMLowOneY", pct(KM["low"]["disposed_by_year_1"], 0)); mac("KMMidOneY", pct(KM["mid"]["disposed_by_year_1"], 0)); mac("KMHighOneY", pct(KM["high"]["disposed_by_year_1"], 0))
mac("KMAllOneY", pct(CX["kaplan_meier_sample_A"]["all"]["disposed_by_year_1"], 0)); mac("KMAllFiveY", pct(CX["kaplan_meier_sample_A"]["all"]["disposed_by_year_5"], 0))
mac("CoxPermHR", r(CX["control_permuted_S"]["hr"], 2)); mac("CoxPHp", r(A["ph_test_rank"]["S"]["p"], 3))

# ---------------- Table 4 Panel A: returns on the signal across specifications (19 published / 29 / 27 / 34)
T6 = IF["table6_returns_on_signal"]; GR = GC["regressions"]
def cellp(v, se_key="se_hc1", pk="p_hc1", d=3): return f"{r(v['coef'], d)}{stars(v[pk])} ({r(v[se_key], d)})"
cols = [("(1)", "Year FE, HC1", T6["rank_1y"]["yearFE_published"]["p_llm"], T6["rank_1y"]["yearFE_published"]["n"], "p_hc1", "se_hc1"),
        ("(2)", "Year + GICS sector FE, firm cluster", T6["rank_1y"]["year+gsector"]["p_llm"], T6["rank_1y"]["year+gsector"]["n"], "p_firm_t", "se_firm_hc0"),
        ("(3)", "Year + GICS sector FE, two-way cluster", T6["rank_1y"]["year+gsector"]["p_llm"], T6["rank_1y"]["year+gsector"]["n"], "p_twoway_t", "se_twoway_cgm"),
        ("(4)", "(1) + Kang--Lee-type purpose and mention dummies", RL["spec3_plus_purpose_mentions"]["p_llm"], RL["spec3_plus_purpose_mentions"]["n"], "p_hc1", "se_hc1"),
        ("(5)", "(1) + foreign ownership", GR["rank_1y"]["spec3_plus_foreign"]["p_llm"], GR["rank_1y"]["spec3_plus_foreign"]["n"], "p_firm", "se_hc1"),
        ("(6)", "(1) + foreign ownership + outside-director ratio (FY2015+)", GR["rank_1y"]["spec3_plus_foreign_board"]["p_llm"], GR["rank_1y"]["spec3_plus_foreign_board"]["n"], "p_firm", "se_hc1")]
body = ["\\begin{tabular}{l>{\\raggedright\\arraybackslash}p{7.2cm}ccr}", "\\toprule", " & Specification & Coefficient on $S$ (s.e.) & $p$ & $n$ \\\\", "\\midrule", "\\multicolumn{5}{l}{\\emph{Panel A. Within-year rank of the one-year market-adjusted BHAR}} \\\\"]
for tag, lab, v, n, pk, sk in cols: body.append(f"{tag} & {lab} & {r(v['coef'], 3)} ({r(v[sk], 3)}) & {pv(v[pk])} & {n} \\\\")
ann = [("(7)", "Year FE, HC1", T6["ann_car"]["yearFE_published"]["p_llm"], T6["ann_car"]["yearFE_published"]["n"], "p_hc1", "se_hc1"),
       ("(8)", "Year + GICS sector FE, firm cluster", T6["ann_car"]["year+gsector"]["p_llm"], T6["ann_car"]["year+gsector"]["n"], "p_firm_t", "se_firm_hc0"),
       ("(9)", "(7) + Kang--Lee-type purpose and mention dummies", AL["spec3_plus_purpose_mentions"]["p_llm"], AL["spec3_plus_purpose_mentions"]["n"], "p_hc1", "se_hc1"),
       ("(10)", "(7) + foreign ownership", GR["ann_car"]["spec3_plus_foreign"]["p_llm"], GR["ann_car"]["spec3_plus_foreign"]["n"], "p_firm", "se_hc1")]
body.append("\\midrule"); body.append("\\multicolumn{5}{l}{\\emph{Panel B. Three-day announcement CAR}} \\\\")
for tag, lab, v, n, pk, sk in ann: body.append(f"{tag} & {lab} & {r(v['coef'], 3)} ({r(v[sk], 3)}) & {pv(v[pk])} & {n} \\\\")
body += ["\\bottomrule", "\\end{tabular}"]
w("T_returns_specs", "\n".join(body), "results/industry_fe_firm_clusters_20261110.json -> table6_returns_on_signal; nested_models_20261110.json -> return_ladder; governance_controls_20261110.json -> regressions")
g = T6["rank_1y"]["year+gsector"]["p_llm"]; mac("RankSSector", r(g["coef"], 3)); mac("RankSSectorPFirm", pv(g["p_firm_t"])); mac("RankSSectorPTwoway", pv(g["p_twoway_t"]))
mac("RankSSic", r(T6["rank_1y"]["year+sic2"]["p_llm"]["coef"], 3)); mac("RankSGind", r(T6["rank_1y"]["year+gind"]["p_llm"]["coef"], 3))
mac("RankSForeign", r(GR["rank_1y"]["spec3_plus_foreign"]["p_llm"]["coef"], 3)); mac("RankSForeignP", pv(GR["rank_1y"]["spec3_plus_foreign"]["p_llm"]["p_firm"])); mac("RankSForeignN", GR["rank_1y"]["spec3_plus_foreign"]["n"])
mac("AnnSForeign", r(GR["ann_car"]["spec3_plus_foreign"]["p_llm"]["coef"], 3)); mac("AnnSForeignP", pv(GR["ann_car"]["spec3_plus_foreign"]["p_llm"]["p_firm"]))   # Table 6 column (10)
mac("RankSBoard", r(GR["rank_1y"]["spec3_plus_foreign_board"]["p_llm"]["coef"], 3)); mac("RankSBoardP", pv(GR["rank_1y"]["spec3_plus_foreign_board"]["p_llm"]["p_firm"])); mac("RankSBoardN", GR["rank_1y"]["spec3_plus_foreign_board"]["n"])
mac("AnnSSector", r(T6["ann_car"]["year+gsector"]["p_llm"]["coef"], 3)); mac("AnnSSectorP", pv(T6["ann_car"]["year+gsector"]["p_llm"]["p_firm_t"]))
# the published specification (year FE + controls, HC1) = Table 5 row (7); \AnnCarSlope (0.037) is the year-FE-only slope of 19 and is no longer quoted
a7 = T6["ann_car"]["yearFE_published"]["p_llm"]; mac("AnnSYearFE", r(a7["coef"], 3)); mac("AnnSYearFESE", r(a7["se_hc1"], 3)); mac("AnnSYearFEP", pv(a7["p_hc1"])); mac("AnnSYearFEPP", r(a7["coef"] * 100, 1))
mac("AnnSPlusPurposeMentionsSE", r(AL["spec3_plus_purpose_mentions"]["p_llm"]["se_hc1"], 3))
mac("ForeignCoverage", GC["foreign"]["coverage"]); mac("ForeignMedian", r(GC["foreign"]["describe_pct"]["50%"], 1)); mac("BoardN", GC["board"]["with_ratio"]); mac("BoardMedian", r(GC["board"]["describe_ratio"]["50%"], 2))
e7 = IF["table7_realized_early_disposal"]["rank_1y"]["year+gsector"]["early_plus_controls"]["early"]; mac("EarlySector", r(e7["coef"], 3)); mac("EarlySectorP", pv(e7["p_firm_t"]))
# rank regression with the signal and realised early disposal entered together (29 -> table7, published spec = year FE + controls, n = events with a recorded timing)
j7 = IF["table7_realized_early_disposal"]["rank_1y"]["yearFE_published"]; mac("JointRankN", j7["score_and_early"]["n"])
mac("JointRankS", r(j7["score_and_early"]["p_llm"]["coef"], 3)); mac("JointRankSP", pv(j7["score_and_early"]["p_llm"]["p_hc1"])); mac("JointRankSPFirm", pv(j7["score_and_early"]["p_llm"]["p_firm_t"]))
mac("JointRankEarly", r(j7["score_and_early"]["early"]["coef"], 3)); mac("JointRankEarlyP", pv(j7["score_and_early"]["early"]["p_hc1"]))
mac("EarlyRankAlone", r(j7["early_plus_controls"]["early"]["coef"], 3)); mac("EarlyRankAloneP", pv(j7["early_plus_controls"]["early"]["p_hc1"]))

# ---------------- Table 4 Panel C (separate fragment): benchmarks (31)
BB = MB["by_benchmark"]
bl = [("Market-adjusted (paper)", "market_adjusted_paper"), ("5$\\times$5 size/B-M portfolio (size fallback)", "pf55_sizeBM_with_size_fallback"), ("5$\\times$5 strict", "pf55_strict"), ("3$\\times$3 size/B-M portfolio", "pf33"),
      ("Matched firm (size, B/M)", "matched_firm_sizeBM"), ("Propensity-matched control firm", "psm_control_firm")]
body = ["\\begin{tabular}{>{\\raggedright\\arraybackslash}p{4.6cm}rcccc}", "\\toprule", "Benchmark & $n$ & Mean BHAR, \\% [95\\% CI] & Spearman($S$) ($p$) & Rank coef.\\ on $S$ ($p$) & Early $-$ never, pp ($p$) \\\\", "\\midrule"]
for lab, k in bl:
    v = BB[k]; body.append(f"{lab} & {v['n']} & {pct(v['mean'], 1, True)} [{pct(v['mean_ci95'][0], 1, True)}, {pct(v['mean_ci95'][1], 1, True)}] & {r(v['spearman_S']['rho'], 3)} ({pv(v['spearman_S']['p'])}) & {r(v['rank_on_S_spec3']['coef'], 3)} ({pv(v['rank_on_S_spec3']['p_firm'])}) & {pp1(v['early_vs_never']['diff_mean_pp'])} ({pv(v['early_vs_never']['mw_p'])}) \\\\")
body += ["\\bottomrule", "\\end{tabular}"]
w("T_benchmarks", "\n".join(body), "results/matched_benchmark_selection_20261113.json -> by_benchmark")
for lab, k in bl:
    key = re.sub(r"[^A-Za-z]", "", k.title()); v = BB[k]; mac(f"Bench{key}Rank", r(v["rank_on_S_spec3"]["coef"], 3)); mac(f"Bench{key}RankP", pv(v["rank_on_S_spec3"]["p_firm"])); mac(f"Bench{key}Mean", pct(v["mean"], 1, True)); mac(f"Bench{key}Rho", r(v["spearman_S"]["rho"], 3)); mac(f"Bench{key}N", v["n"])
    mac(f"Bench{key}EarlyNever", pp1(v["early_vs_never"]["diff_mean_pp"])); mac(f"Bench{key}EarlyNeverP", pv(v["early_vs_never"]["mw_p"])); mac(f"Bench{key}NEarly", v["early_vs_never"]["n_early"]); mac(f"Bench{key}NNever", v["early_vs_never"]["n_never"])
SL = MB["selection_logit"]; mac("SelFirmYears", f"{SL['firm_years']:,}"); mac("SelEvents", SL["events"]); mac("SelFirms", f"{SL['firms']:,}"); mac("SelPseudoR", r(SL["pseudo_r2"], 3))
for k in ("log_at", "lev", "cf", "sg", "kosdaq", "q", "inv", "cash"): mac(f"Sel{re.sub('[^A-Za-z]', '', k.title())}", r(SL["coef"][k]["coef"], 3)); mac(f"Sel{re.sub('[^A-Za-z]', '', k.title())}P", pv(SL["coef"][k]["p_firm"]))
mac("SelPSAUC", r(SL["propensity"]["auc_of_ps"], 2)); mac("SelSupport", pct(SL["propensity"]["event_in_control_support_share"], 0))
body = ["\\begin{tabular}{lcc}", "\\toprule", "Covariate (year $t-1$) & Coefficient (firm-clustered s.e.) & $p$ \\\\", "\\midrule"]
labs = {"log_at": "log total assets", "q": "Tobin's $q$", "lev": "Leverage", "inv": "Investment / assets", "cf": "Cash flow / assets", "cash": "Cash / assets", "sg": "Sales growth", "kosdaq": "KOSDAQ", "parent_only": "Parent-only accounts"}
for k, lab in labs.items():
    v = SL["coef"][k]; body.append(f"{lab} & {r(v['coef'], 3)}{stars(v['p_firm'])} ({r(v['se_firm'], 3)}) & {pv(v['p_firm'])} \\\\")
body += ["\\midrule", f"Firm-years / events / firms & \\multicolumn{{2}}{{c}}{{{SL['firm_years']:,} / {SL['events']} / {SL['firms']:,}}} \\\\", f"Pseudo-$R^2$; AUC of the propensity score & \\multicolumn{{2}}{{c}}{{{r(SL['pseudo_r2'], 3)}; {r(SL['propensity']['auc_of_ps'], 2)}}} \\\\", "\\bottomrule", "\\end{tabular}"]
w("S_selection", "\n".join(body), "results/matched_benchmark_selection_20261113.json -> selection_logit")

