# ---------------- JIFMA copies of inherited fragments whose cross-references point at the CGIR table labels
LABEL_MAP = {"tab:returns_by_score": "tab:returns", "tab:controls": "tab:returns", "tab:realized_controls": "tab:returns", "tab:returns_by_outcome": "tab:returns",
             "tab:block_terciles": "tab:block", "tab:block_regressions": "tab:block"}
for name in ("S_defs_full", "T_defs_short", "T_mirror", "T_sample"):
    t = open(f"{OUT}/{name}.tex", encoding="utf-8").read()
    for a, b in LABEL_MAP.items(): t = t.replace("\\ref{" + a + "}", "\\ref{" + b + "}")
    # several CGIR tables map onto one JIFMA table: collapse "Tables~\\ref{X}, \\ref{X}, \\ref{Y}" to "Tables~\\ref{X}, \\ref{Y}" (and to "Table~\\ref{X}" when one remains)
    def _dedupe(m):
        refs = []
        for k in re.findall(r"\\ref\{([^}]+)\}", m.group(0)):
            if k not in refs: refs.append(k)
        return ("Tables~" if len(refs) > 1 else "Table~") + ", ".join("\\ref{" + k + "}" for k in refs)
    t = re.sub(r"Tables~\\ref\{[^}]+\}(?:, \\ref\{[^}]+\})+", _dedupe, t)
    t = t.replace("Anonymized", "Anonymised").replace("anonymized", "anonymised").replace("Realized", "Realised").replace("realized", "realised")  # JIFMA prose is British
    open(f"{OUT}/{name}_jifma.tex", "w", encoding="utf-8").write(t.replace("generated by code/make_tables_cgir.py", "generated by code/make_tables_cgir.py (labels remapped by make_tables_jifma.py)"))


